    32	/// The last name of a typed path: the text after its last separator, the
    33	/// separators after that name set aside. Empty for a path that holds no
    34	/// name at all.
    35	pub fn final_name(typed: &[u8]) -> &[u8] {
    36	    let end = typed
    37	        .iter()
    38	        .rposition(|&byte| byte != b'/')
    39	        .map_or(0, |last| last + 1);
    40	    let named = &typed[..end];
    41	    match named.iter().rposition(|&byte| byte == b'/') {
    42	        Some(separator) => &named[separator + 1..],
    43	        None => named,
    44	    }
    45	}
    46	
    47	/// The path's last name is `.` or `..` — what `rm` refuses to remove,
    48	/// whatever its options (`refusing to remove '.' or '..' directory`).
    49	pub fn names_dot(typed: &[u8]) -> bool {
    50	    matches!(final_name(typed), b"." | b"..")
    51	}
    52	
    53	/// The path is written so that it names a directory and nothing else: with
    54	/// a separator after it, or with `.` as its last name. The system then
    55	/// resolves a link standing there and refuses anything that is no
    56	/// directory (`Not a directory`).
    57	pub fn names_a_directory(typed: &[u8]) -> bool {
    58	    typed.ends_with(b"/") || final_name(typed) == b"."
    59	}
    60	
    61	/// The path holds no name: only separators and `.`. It is the module
    62	/// itself.
    63	pub fn is_the_root(typed: &[u8]) -> bool {
    64	    typed
    65	        .split(|&byte| byte == b'/')
    66	        .all(|part| part.is_empty() || part == b".")
    67	}
