    69	/// The bytes of a command-line word. On Unix a word is bytes, and they
    70	/// are these; elsewhere a word is text or it is refused.
    71	pub fn word_bytes(word: &OsStr) -> Result<&[u8]> {
    72	    #[cfg(unix)]
    73	    {
    74	        use std::os::unix::ffi::OsStrExt as _;
    75	        Ok(word.as_bytes())
    76	    }
