    86	/// A utility verb's operand as typed: `HOST:/MODULE/PATH` or
    87	/// `HOST://PATH`, the path by its bytes.
    88	#[derive(Debug, Clone)]
    89	pub struct Operand {
    90	    /// The daemon it names.
    91	    pub remote: RemoteEndpoint,
    92	    /// The module; empty for the default root (`HOST://`).
    93	    pub module: String,
    94	    /// The whole operand, as typed.
    95	    typed: Vec<u8>,
    96	    /// Where in it the path below the module begins.
    97	    path_at: usize,
    98	}
    99	
   100	impl Operand {
   101	    /// Read one operand. `Ok(None)` is a word that names no daemon — a
   102	    /// local path. An operand that names a daemon and no module, or whose
   103	    /// host or module is not text, is an error.
   104	    pub fn read(word: &OsStr) -> Result<Option<Self>> {
   105	        let typed = word_bytes(word)?;
   106	        // The daemon and the module are text, and stand before the path:
   107	        // they are read from the text the operand begins with. Whatever
   108	        // in the PATH is not text stays as the bytes it is.
   109	        let (text, all_text) = match std::str::from_utf8(typed) {
   110	            Ok(text) => (text, true),
   111	            Err(error) => (
   112	                std::str::from_utf8(&typed[..error.valid_up_to()]).expect("valid up to there"),
   113	                false,
   114	            ),
   115	        };
   116	        let holds_a_path = |remote: &RemoteEndpoint| !matches!(remote.path, RemotePath::Discovery);
   117	        let read = RemoteEndpoint::parse(text)
   118	            .ok()
   119	            .filter(holds_a_path)
   120	            .and_then(|remote| Some((remote, RemoteEndpoint::path_offset(text)?)));
   121	        let Some((remote, path_at)) = read else {
   122	            // Does the whole word, read leniently, name a daemon at all?
   123	            let lenient = String::from_utf8_lossy(typed);
   124	            return match RemoteEndpoint::parse(&lenient) {
   125	                Err(_) => Ok(None),
   126	                Ok(_) if !all_text => {
   127	                    bail!("the daemon and the module in `{lenient}` must be valid text")
   128	                }
   129	                Ok(_) => {
   130	                    bail!("remote target must include a module path (e.g., server:/module/path)")
   131	                }
   132	            };
   133	        };
   134	        let module = match &remote.path {
   135	            RemotePath::Module { module, .. } => module.clone(),
   136	            _ => String::new(),
   137	        };
   138	        Ok(Some(Self {
   139	            remote,
   140	            module,
   141	            typed: typed.to_vec(),
   142	            path_at,
   143	        }))
   144	    }
   145	
   146	    /// The path below the module exactly as typed: no separator dropped,
   147	    /// no `.` folded away, no space trimmed, no byte replaced. (Separators
   148	    /// between the module and the first name belong to neither.)
   149	    pub fn path(&self) -> &[u8] {
   150	        let path = &self.typed[self.path_at..];
   151	        let lead = path.iter().take_while(|&&byte| byte == b'/').count();
   152	        &path[lead..]
   153	    }
   154	
   155	    /// That path as a request carries it: its text, and its own bytes
   156	    /// when they are not text.
   157	    pub fn wire_path(&self) -> EntryPath {
   158	        EntryPath::typed(self.path())
   159	    }
   160	
   161	    /// The operand as typed, by its bytes — what the commands print.
   162	    pub fn typed(&self) -> &[u8] {
   163	        &self.typed
   164	    }
   165	
   166	    /// The operand as typed, as text for a message.
   167	    pub fn shown(&self) -> String {
   168	        String::from_utf8_lossy(&self.typed).into_owned()
   169	    }
   170	
   171	    /// An entry below this operand as `du` and `rm` print it: the operand
   172	    /// as typed for the operand itself; below it the operand, ONE
   173	    /// separator, and the entry's path — `dir/` and `dir` both print
