   176	    /// `HOST://sub`. (cr-uv1-4: it was printed `HOST:/sub`, which names a
   177	    /// module called `sub`.)
   178	    pub fn below(&self, entry: &EntryPath) -> Vec<u8> {
   179	        if entry.is_start() {
   180	            return self.typed.clone();
   181	        }
   182	        let (daemon, path) = self.typed.split_at(self.path_at);
   183	        let end = path
   184	            .iter()
   185	            .rposition(|&byte| byte != b'/')
   186	            .map_or(0, |last| last + 1);
   187	        let mut shown = daemon.to_vec();
