   189	        if end > 0 {
   190	            shown.push(b'/');
   191	        }
   192	        shown.extend_from_slice(entry.bytes());
   193	        shown
   194	    }
   195	
   196	    /// An entry below this operand as `find` prints it: the operand as
   197	    /// typed, a separator unless it ends in one, and the entry's path —
   198	    /// `dir//` prints `dir//sub`, every separator typed kept.
   199	    pub fn below_as_find(&self, entry: &EntryPath) -> Vec<u8> {
   200	        let mut shown = self.typed.clone();
   201	        if entry.is_start() {
   202	            return shown;
   203	        }
   204	        if !shown.ends_with(b"/") {
   205	            shown.push(b'/');
   206	        }
   207	        shown.extend_from_slice(entry.bytes());
   208	        shown
   209	    }
   210	}
